parameters.jsCode:
const lead = $('Lead Webhook').first().json.body;

const text = (
  (lead.message || '') + ' ' +
  (lead.company || '')
).toLowerCase();

let score = 20;

const urgent = [
  'urgent', 'asap', 'this month',
  'this week', 'immediately', 'start now'
];

const budget = [
  'budget', 'ready to pay',
  'invest', 'approved'
];

const need = [
  'voice', 'ai agent', 'automation',
  'crm', 'chatbot', 'sales team', 'integration'
];

if (urgent.some(k => text.includes(k))) score += 30;
if (budget.some(k => text.includes(k))) score += 30;
if (need.some(k => text.includes(k))) score += 15;
if (lead.phone) score += 5;
if (lead.company) score += 5;

score = Math.min(score, 100);

const category =
  score >= 70 ? 'hot' :
  score >= 40 ? 'warm' : 'cold';

const summary =
  'Rule-based score ' + score +
  '/100. Message: ' +
  (lead.message || 'n/a').slice(0, 120);

const next_action =
  category === 'hot'
    ? 'Call within 24 hours'
    : category === 'warm'
    ? 'Send intro email and case study'
    : 'Add to nurture list';

return [{
  json: {
    ...lead,
    score,
    category,
    summary,
    next_action
  }
}];

